#[path="observations.rs"]mod observations;
use observations::median;use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-ready-arithmetic");let config=read(r.join("perf-plan.json"));let result=read(r.join("performance/result.json"));assert_eq!(result["status"],"complete");
 for(p,h)in config["pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap(),"pin {p}");}
 let rows=read(r.join("performance/rows.json"));let rows=rows.as_array().unwrap();assert_eq!(rows.len(),30);
 let mut cases=BTreeMap::new();let mut calibration_failures=Vec::new();let mut trace_failures=Vec::new();let mut details=Vec::new();let mut sdk=24usize;let mut sample_count=0u64;
 for c in config["cases"].as_array().unwrap(){let name=c["name"].as_str().unwrap();let mut summaries=BTreeMap::new();
  for variant in ["accepted","off","on"]{let selected:Vec<_>=rows.iter().filter(|x|x["case"]==name&&x["variant"]==variant&&x["phase"]=="latency").collect();assert_eq!(selected.len(),3);summaries.insert(variant,json!({"request_ms":median(selected.iter().map(|x|x["median_ms"].as_f64().unwrap()).collect()),"whole_process_maxrss_mib":selected.iter().map(|x|x["summary"]["whole_process_maxrss_kib"].as_f64().unwrap()/1024.0).fold(0.,f64::max)}));}
  let mut off_ratios=Vec::new();let mut on_ratios=Vec::new();let mut captures=Vec::new();let mut kind_data:BTreeMap<String,Vec<Value>>=BTreeMap::new();
  for block in 0..3 {let find=|variant:&str|rows.iter().find(|x|x["case"]==name&&x["variant"]==variant&&x["phase"]=="latency"&&x["block"]==block).unwrap();let a=find("accepted")["median_ms"].as_f64().unwrap();let off=find("off")["median_ms"].as_f64().unwrap();let on=find("on")["median_ms"].as_f64().unwrap();let cr=off/a;let tr=on/off;off_ratios.push(cr);on_ratios.push(tr);if cr>1.03||cr<1./1.03{calibration_failures.push(format!("{name}/b{block} OFF/accepted={cr}"));}if tr>1.05||tr<1./1.05{trace_failures.push(format!("{name}/b{block} ON/OFF={tr}"));}
   let stem=Path::new(c["image"].as_str().unwrap()).file_stem().unwrap();let dir=r.join(format!("performance/latency/b{block}/{name}/on/proofs")).join(stem);let observed=read(dir.join("readiness.json"));assert_eq!(observed.as_array().unwrap().len(),17);
   for(i,proof)in observed.as_array().unwrap().iter().enumerate(){assert_eq!(proof["round"],i);let a=observations::inspect(proof,c["workers"].as_u64().unwrap()as usize);for(k,v)in a["kinds"].as_object().unwrap(){kind_data.entry(k.clone()).or_default().push(v.clone());}captures.push(a.clone());details.push(json!({"case":name,"block":block,"round":i,"observation":a}));}
  }
  let ratio=median(on_ratios.clone());if ratio>1.03||ratio<1./1.03{trace_failures.push(format!("{name} paired median ON/OFF={ratio}"));}
  let mut metrics=BTreeMap::new();for key in ["units","cancelled","batches","interval_ms","sum_leaf_elapsed_ms","mean_observed_running_leaves","mean_declared_pending_units","peak_declared_pending_units","pending_with_less_than_half_workers_observed_running_fraction","last_tenth_pending_with_less_than_half_workers_observed_running_fraction"]{metrics.insert(key,median(captures.iter().map(|x|x[key].as_f64().unwrap()).collect()));}
  let mut kinds=BTreeMap::new();for(kind,values)in kind_data{let mut med=BTreeMap::new();for key in["units","sum_leaf_elapsed_ms","median_leaf_us","p95_leaf_us","median_declared_ready_delay_us","p95_declared_ready_delay_us"]{med.insert(key,median(values.iter().map(|x|x[key].as_f64().unwrap()).collect()));}kinds.insert(kind,med);}
  cases.insert(name,json!({"latency":summaries,"off_accepted_block_ratios":off_ratios,"on_off_block_ratios":on_ratios,"off_accepted_paired_median":median(off_ratios),"on_off_paired_median":ratio,"trace_metrics_median":metrics,"kinds_median":kinds}));
 }
 let mut profiles=BTreeMap::new();for row in rows {let rounds=if row["phase"]=="latency"{17}else{51};assert_eq!(row["samples_ms"].as_array().unwrap().len(),rounds);assert_eq!(row["summary"]["rounds"],rounds);sdk+=rounds+3;
  if row["phase"]=="profile"{assert_eq!(row["case"],"1x2-w32");let p=&row["profile"];assert_eq!(p["lost_records"],0);assert_eq!(p["sampled_pids"].as_array().unwrap().len(),1);sample_count+=p["samples"].as_u64().unwrap();profiles.insert(row["variant"].as_str().unwrap().to_owned(),p.clone());if row["variant"]=="on"{let p=r.join("performance/profile/b0/1x2-w32/on/proofs/transfer_confidential_1_2/readiness.json");let v=read(p);assert_eq!(v.as_array().unwrap().len(),51);for x in v.as_array().unwrap(){observations::inspect(x,32);}}}
 }
 assert_eq!(sdk,726);let inventory=read(r.join("performance/proof-inventory.json"));assert_eq!(inventory.as_object().unwrap().len(),60);for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(r.join("performance").join(p)),h.as_str().unwrap());}
 let out=json!({"scope":"Local current-build diagnostic, not a new algorithm, C7a measurement or accepted speed result. Declared independent units are not actual executor queue length. Leaf elapsed time is not CPU self-time or a complete critical path.","sdk_requests":sdk,"distinct_gnark_exports":36,"proof_public_members":72,"latency_processes":27,"latency_trace_observations":153,"profile_trace_observations":51,"profile_samples":sample_count,"profiles":profiles,"calibration_failures":calibration_failures,"tracing_failures":trace_failures,"timing_qualified":calibration_failures.is_empty()&&trace_failures.is_empty(),"recorder_bytes":1572864,"cases":cases,"observations":details,"production_changed":false,"adopted":false,"goal_achieved":false});
 fs::write(r.join("analysis.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Completed726SDK36Gnark,153latency+51profile task snapshots; profiles{}samples; diagnostic timing qualified={}",sample_count,out["timing_qualified"]);
}
